CREATE TABLE institutions (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE memberships (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), institution_id TEXT REFERENCES institutions(id), role TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE regulations (id TEXT PRIMARY KEY NOT NULL, institution_id TEXT NOT NULL REFERENCES institutions(id), created_at TEXT NOT NULL);
CREATE TABLE regulation_versions (id TEXT PRIMARY KEY NOT NULL, regulation_id TEXT NOT NULL REFERENCES regulations(id), version_number INTEGER NOT NULL, source_document_version_id TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(regulation_id, version_number));
CREATE TABLE processes (id TEXT PRIMARY KEY NOT NULL, institution_id TEXT NOT NULL REFERENCES institutions(id), regulation_version_id TEXT REFERENCES regulation_versions(id), phase TEXT NOT NULL, status TEXT NOT NULL, created_by_user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE attorney_assignments (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), user_id TEXT NOT NULL REFERENCES users(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(process_id, user_id));
CREATE TABLE workflow_blocks (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), scope TEXT NOT NULL, reason TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE documents (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), kind TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE document_versions (id TEXT PRIMARY KEY NOT NULL, document_id TEXT NOT NULL REFERENCES documents(id), version_number INTEGER NOT NULL, author_user_id TEXT NOT NULL REFERENCES users(id), origin TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(document_id, version_number));
CREATE TABLE files (id TEXT PRIMARY KEY NOT NULL, document_version_id TEXT NOT NULL REFERENCES document_versions(id), storage_key TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE version_actions (id TEXT PRIMARY KEY NOT NULL, document_version_id TEXT NOT NULL REFERENCES document_versions(id), actor_user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE secop_evidence (id TEXT PRIMARY KEY NOT NULL, document_version_id TEXT NOT NULL REFERENCES document_versions(id), reference TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY NOT NULL, process_id TEXT NOT NULL REFERENCES processes(id), assigned_user_id TEXT REFERENCES users(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE alerts (id TEXT PRIMARY KEY NOT NULL, user_id TEXT REFERENCES users(id), institution_id TEXT REFERENCES institutions(id), process_id TEXT REFERENCES processes(id), channel TEXT NOT NULL, status TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY NOT NULL, process_id TEXT REFERENCES processes(id), actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, result TEXT, created_at TEXT NOT NULL);
CREATE INDEX memberships_user_idx ON memberships(user_id); CREATE INDEX memberships_institution_idx ON memberships(institution_id); CREATE INDEX processes_institution_idx ON processes(institution_id); CREATE INDEX attorney_assignment_user_idx ON attorney_assignments(user_id); CREATE INDEX documents_process_idx ON documents(process_id); CREATE INDEX jobs_pending_idx ON jobs(status, available_at);
